from pathlib import Path

# 1) Make the primary Read structurally distinct across the full slate.
path = Path('src/nfl_forecast/editorial_voice.py')
text = path.read_text()
needle = '''    def beat(item: dict[str, Any]) -> str:\n        title = str(item.get("title") or "").strip().rstrip('.:')\n        summary = specific_summary(item)\n        return summary if not title or title.lower() in summary.lower()[: max(90, len(title) + 15)] else f"{title}: {summary}"\n\n    special_families = {"international_event", "rivalry", "international_travel"}\n'''
replacement = '''    def beat(item: dict[str, Any]) -> str:\n        title = str(item.get("title") or "").strip().rstrip('.:')\n        summary = specific_summary(item)\n        return summary if not title or title.lower() in summary.lower()[: max(90, len(title) + 15)] else f"{title}: {summary}"\n\n    def read_hook(slot: int, item: dict[str, Any], pick: str, opponent: str) -> str:\n        title = str(item.get("title") or _label(family(item))).strip().rstrip('.:')\n        hooks = [\n            f"{title} gets first billing in this file. It is the sourced matchup fact that most clearly explains why {pick} has a path to control the terms rather than merely survive them.",\n            f"The opening question is not the spread; it is {title}. That evidence tells us which part of the field {opponent} must solve before the broader forecast can be trusted.",\n            f"Build the football case from {title} outward. The number matters because this particular matchup can dictate play selection, down-and-distance, and the kind of possessions both staffs are forced to manage.",\n            f"{title} is the hinge worth isolating before anything else. If that edge shows up as the source data suggests, the {pick} projection has a concrete mechanism instead of a generic favorite's argument.",\n            f"This matchup file starts below the headline level with {title}. It gives the forecast a tactical center of gravity and identifies exactly where {opponent} has to keep the game from tilting.",\n            f"The most useful first read is {title}, not a broad power-rating story. That sourced detail narrows the game to a football problem the {pick} side can repeatedly test.",\n            f"There is one place to begin the film-room version of this forecast: {title}. Its value is that it connects the underlying data to a repeatable on-field question for both teams.",\n            f"{title} deserves the first paragraph because it can alter the menu available to each coordinator. That makes it more informative for this game than a generic statement about which roster is stronger.",\n            f"Strip away the win probability for a moment and look at {title}. This is the evidence thread most capable of turning the model's preference into a recognizable game script.",\n            f"The clearest route from data to football runs through {title}. It tells us what {pick} can press, what {opponent} must protect, and where the forecast is most likely to become visible.",\n            f"Treat {title} as the matchup's organizing fact. It does not decide the game by itself, but it gives the {pick} case a specific lever that can be checked snap by snap.",\n            f"Before the game branches into turnovers, fourth downs, and variance, {title} supplies the cleanest baseline. It is the part of this matchup where the evidence gives one side a defined structural advantage.",\n            f"The first layer of this forecast is {title}. That detail matters because it can force a response from {opponent}, and forced responses are where a pregame edge starts changing the rest of the call sheet.",\n            f"{title} is the best place to test whether the model's preference has real football substance. The evidence there creates a matchup-specific burden that {opponent} cannot solve with probability or reputation.",\n            f"Rather than start with the final percentage, start with {title}. It provides the most concrete explanation for how {pick} can create leverage and where the opposing plan has to be unusually clean.",\n            f"This read is anchored by {title} because it links source data to an identifiable coaching decision. If the matchup behaves that way, the {pick} side can make the game look like its preferred version.",\n        ]\n        return hooks[slot % len(hooks)]\n\n    special_families = {"international_event", "rivalry", "international_travel"}\n'''
if needle not in text:
    raise SystemExit('beat insertion point missing')
text = text.replace(needle, replacement)
old = '''        if selected:\n            preview["headline"] = str(selected[0].get("title") or f"{away}-{home}").strip()\n            lead = " ".join(beat(item) for item in selected[:2]).strip()\n        else:\n'''
new = '''        if selected:\n            preview["headline"] = str(selected[0].get("title") or f"{away}-{home}").strip()\n            evidence_beats = " ".join(beat(item) for item in selected[:2]).strip()\n            if family(selected[0]) in special_families:\n                lead = evidence_beats\n            else:\n                lead = f"{read_hook(slate_index, selected[0], pick, opponent)} {evidence_beats}".strip()\n        else:\n'''
if old not in text:
    raise SystemExit('lead block missing')
path.write_text(text.replace(old, new))

# 2) The later story-desk pass must not overwrite slate-aware public prose with
# raw evidence summaries. It may still promote genuinely special event/rivalry
# context and extend the notebook.
path = Path('scripts/polish_publication.py')
text = path.read_text()
needle = '''        counter = _best(items, lambda item: _advantage(item) == opponent and _family(item) not in {"rivalry", "international_event", "international_travel"})\n\n        final_pick = _pick_prob(row, "final_home_prob")\n'''
replacement = '''        counter = _best(items, lambda item: _advantage(item) == opponent and _family(item) not in {"rivalry", "international_event", "international_travel"})\n\n        # `run_context.py` now produces a slate-aware, game-specific public voice.\n        # Do not replace that copy downstream with raw evidence summaries, which\n        # can share template tails across games. Story-desk still owns genuinely\n        # special event/rivalry promotion and notebook enrichment.\n        if bool((preview.get("editorial_voice") or {}).get("game_specific")):\n            special_first = None\n            if event and {away, home} == {"SF", "LA"}:\n                preview["headline"] = "Rams-49ers takes a 154-game rivalry to Melbourne"\n                special_first = (\n                    "The Rams and 49ers have played 154 times, but never like this. Their season opens at the Melbourne Cricket Ground in the NFL's first regular-season game in Australia, "\n                    "after the longest single-game city-to-city travel haul in league history. San Francisco leads the all-time series 79-72-3, so the opponent is familiar even if almost everything around the game is new."\n                )\n            elif rivalry:\n                preview["headline"] = _expand(rivalry.get("title") or preview.get("headline") or f"{away}-{home}")\n                special_first = _expand(rivalry.get("summary") or "")\n\n            if special_first:\n                paragraphs = list(preview.get("paragraphs") or [])\n                if paragraphs:\n                    paragraphs[0] = special_first.strip()\n                else:\n                    paragraphs = [special_first.strip()]\n                preview["paragraphs"] = paragraphs\n\n            notebook = list(preview.get("notebook") or [])\n            existing_titles = {str(item.get("title") or "") for item in notebook}\n            for item in (event, rivalry, travel):\n                if not item:\n                    continue\n                title = _expand(item.get("title") or "Notebook")\n                if title in existing_titles:\n                    continue\n                notebook.append({\n                    "title": title,\n                    "summary": _expand(item.get("summary") or ""),\n                    "source_url": item.get("source_url"),\n                })\n                existing_titles.add(title)\n            preview["notebook"] = notebook[:5]\n            preview["editorial_version"] = "story-desk-v3"\n            continue\n\n        final_pick = _pick_prob(row, "final_home_prob")\n'''
if needle not in text:
    raise SystemExit('story-desk preservation insertion point missing')
path.write_text(text.replace(needle, replacement))

# 3) Regression tests for the downstream preservation rule.
path = Path('tests/test_publication_polish.py')
text = path.read_text()
addition = '''\n\ndef test_story_desk_preserves_game_specific_voice_outside_special_story():\n    predictions = pd.DataFrame([{\n        "game_id":"g","away_team":"AAA","home_team":"BBB","pick":"BBB",\n        "final_home_prob":.61,"pure_home_prob":.62,"market_home_prob":.58,"model_disagreement":.04,\n    }])\n    evidence = {"g": [\n        {"category":"scheme","title":"AAA protection vs BBB pass rush","summary":"AAA gave up sacks on 8.0% of pass plays; BBB got home on 9.0%. If this turns into an obvious-passing-down game, that matchup gets loud fast.","strength":"Strong","sample_size":400,"metadata":{"family":"pressure","advantage_team":"BBB"}},\n        {"category":"scheme","title":"BBB explosives vs AAA prevention","summary":"BBB owns a separate explosive-play edge.","strength":"Strong","sample_size":400,"metadata":{"family":"explosives","advantage_team":"BBB"}},\n    ]}\n    previews = {"g": {\n        "headline":"AAA protection vs BBB pass rush",\n        "paragraphs":["A deliberately game-specific Read.", "A market paragraph that must survive."],\n        "case_for_pick":"BBB's case is already composed for this matchup.",\n        "case_for_opponent":"AAA's countercase is already composed for this matchup.",\n        "what_could_make_us_wrong":"A matchup-specific failure mode.",\n        "editorial_voice":{"game_specific":True,"slate_aware":True},\n    }}\n    rewrite_previews(predictions, previews, evidence)\n    preview = previews["g"]\n    assert preview["paragraphs"] == ["A deliberately game-specific Read.", "A market paragraph that must survive."]\n    assert preview["case_for_pick"] == "BBB's case is already composed for this matchup."\n    assert preview["case_for_opponent"] == "AAA's countercase is already composed for this matchup."\n    assert "obvious-passing-down" not in " ".join([preview["case_for_pick"], preview["case_for_opponent"]])\n\n\ndef test_story_desk_can_promote_special_event_without_overwriting_cases():\n    predictions = pd.DataFrame([{\n        "game_id":"2026_01_SF_LA","away_team":"SF","home_team":"LA","pick":"LA",\n        "final_home_prob":.70,"pure_home_prob":.72,"market_home_prob":.64,"model_disagreement":.04,\n    }])\n    evidence = {"2026_01_SF_LA": [\n        {"category":"travel","title":"Australia","summary":"First NFL regular-season game in Australia.","strength":"Strong","metadata":{"family":"international_event"}},\n        {"category":"history","title":"Rivalry","summary":"San Francisco leads the all-time series 79-72-3.","strength":"Strong","sample_size":154,"metadata":{"family":"rivalry"}},\n        {"category":"scheme","title":"LA explosives vs SF","summary":"LA created more explosive passes in the relevant sample.","strength":"Strong","sample_size":700,"metadata":{"family":"explosives","advantage_team":"LA"}},\n    ]}\n    previews = {"2026_01_SF_LA": {\n        "headline":"Matthew Stafford vs SF: player history",\n        "paragraphs":["Original game-specific lead.", "Original market paragraph."],\n        "case_for_pick":"Keep the LA case.",\n        "case_for_opponent":"Keep the SF case.",\n        "what_could_make_us_wrong":"Keep the failure mode.",\n        "editorial_voice":{"game_specific":True,"slate_aware":True},\n    }}\n    rewrite_previews(predictions, previews, evidence)\n    preview = previews["2026_01_SF_LA"]\n    assert preview["headline"] == "Rams-49ers takes a 154-game rivalry to Melbourne"\n    assert "Melbourne Cricket Ground" in preview["paragraphs"][0]\n    assert preview["paragraphs"][1] == "Original market paragraph."\n    assert preview["case_for_pick"] == "Keep the LA case."\n    assert preview["case_for_opponent"] == "Keep the SF case."\n'''
if 'test_story_desk_preserves_game_specific_voice_outside_special_story' not in text:
    text += addition
path.write_text(text)
